test('LEVEL-UI-RED-004 teaching cues stay readable and anchored relaunch persists until action', () => {
  const memory = new PromptCueMemory();
  const start = promptCue(1, 120, 'ready', [], [], 366, 0);
  assert.equal(memory.resolve(start, 0)?.kind, 'start');
  assert.equal(memory.resolve(start, 500)?.kind, 'start', 'the first cue remains readable while the player is still ready');
  assert.equal(memory.resolve(start, 4_500)?.kind, 'start', 'slow first-load time must not hide the start cue');

  const wait = promptCue(1, 700, 'airborne', [], [], 385, -80);
  assert.equal(memory.resolve(wait, 4_600)?.kind, 'wait', 'the first tap hands the display to the waiting cue');
  assert.equal(memory.resolve(promptCue(1, 700, 'anchored', [], [], 403, 0), 4_700)?.kind, 'relaunch', 'an anchored relaunch cue must replace stale flight guidance');
  assert.equal(memory.resolve(promptCue(1, 700, 'airborne', [], [], 385, -80), 5_100)?.kind, 'wait', 'takeoff clears the old relaunch cue');
  assert.equal(memory.resolve(promptCue(1, 700, 'anchored', [], [], 403, 0), 5_200)?.kind, 'relaunch', 'the next anchored encounter must repeat the relaunch cue');
  assert.equal(memory.resolve(start, 5_300)?.kind, 'relaunch', 'a start cue cannot replace an active relaunch cue');

